import crypto from "crypto";

const AUTH_SECRET = process.env.AUTH_SECRET || "hsk-secure-jwt-auth-secret-key-2026";

export interface ClassniaTokenPayload {
  userId: string;
  email: string;
  role: string;
  exp: number;
}

/**
 * Verifies an HMAC-signed token generated by classnia.id.vn (hsk_session_token)
 */
export function verifyClassniaToken(token: string): ClassniaTokenPayload | null {
  try {
    const parts = token.split(".");
    if (parts.length !== 2) return null;
    const [payloadB64, signature] = parts;

    const expectedSig = crypto
      .createHmac("sha256", AUTH_SECRET)
      .update(payloadB64)
      .digest("base64url");

    const sigBuf = Buffer.from(signature);
    const expBuf = Buffer.from(expectedSig);

    if (sigBuf.length !== expBuf.length) {
      return null;
    }

    if (!crypto.timingSafeEqual(sigBuf, expBuf)) {
      return null;
    }

    const payload = JSON.parse(
      Buffer.from(payloadB64, "base64url").toString("utf8")
    ) as ClassniaTokenPayload;

    if (payload.exp && payload.exp < Math.floor(Date.now() / 1000)) {
      return null; // Expired token
    }

    return payload;
  } catch {
    return null;
  }
}

/**
 * Creates a Classnia-compatible HMAC-signed token
 */
export function createClassniaToken(
  user: { id: string; email: string; role: string },
  expiresInSeconds = 7 * 24 * 3600
): string {
  const payload: ClassniaTokenPayload = {
    userId: user.id,
    email: user.email.toLowerCase(),
    role: user.role,
    exp: Math.floor(Date.now() / 1000) + expiresInSeconds,
  };

  const payloadB64 = Buffer.from(JSON.stringify(payload)).toString("base64url");
  const signature = crypto
    .createHmac("sha256", AUTH_SECRET)
    .update(payloadB64)
    .digest("base64url");

  return `${payloadB64}.${signature}`;
}
